import{I as e,N as t,S as n,i as r,w as i,x as a}from"./app-DgX_X1fA.js";var o=JSON.parse(`{"path":"/interview/intervie_Kubernetes/intervie_Kubernetes.html","title":"Kubernetes常见面试题","lang":"zh-CN","frontmatter":{"title":"Kubernetes常见面试题","icon":"circle-info","order":1,"category":["面试题"],"tag":["Kubernetes常见面试题","运维"],"date":"2026-02-07T00:00:00.000Z","isOriginal":true,"pageview":true,"article":false,"breadcrumb":false,"comment":true,"description":"1.说下k8s的核心组件都有哪些，并简述下他们各自的作用 答： Kubernetes（k8s）的核心组件可以分为控制平面（Control Plane）组件和工作节点（Node）组件两大类； 控制平面组件（Control Plane Components） etcd：分布式键值存储，保存集群状态。 kube-apiserver：提供 Kubernetes...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"WebPage\\",\\"name\\":\\"Kubernetes常见面试题\\",\\"description\\":\\"1.说下k8s的核心组件都有哪些，并简述下他们各自的作用 答： Kubernetes（k8s）的核心组件可以分为控制平面（Control Plane）组件和工作节点（Node）组件两大类； 控制平面组件（Control Plane Components） etcd：分布式键值存储，保存集群状态。 kube-apiserver：提供 Kubernetes...\\"}"],["meta",{"property":"og:url","content":"http://liuchenyang.top/ToLiucyLinux/interview/intervie_Kubernetes/intervie_Kubernetes.html"}],["meta",{"property":"og:site_name","content":"ToLiucyLinux"}],["meta",{"property":"og:title","content":"Kubernetes常见面试题"}],["meta",{"property":"og:description","content":"1.说下k8s的核心组件都有哪些，并简述下他们各自的作用 答： Kubernetes（k8s）的核心组件可以分为控制平面（Control Plane）组件和工作节点（Node）组件两大类； 控制平面组件（Control Plane Components） etcd：分布式键值存储，保存集群状态。 kube-apiserver：提供 Kubernetes..."}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-09-03T12:38:29.000Z"}],["meta",{"property":"article:tag","content":"运维"}],["meta",{"property":"article:tag","content":"Kubernetes常见面试题"}],["meta",{"property":"article:published_time","content":"2026-02-07T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-03T12:38:29.000Z"}]]},"git":{"createdTime":1737021380000,"updatedTime":1788439109000,"contributors":[{"name":"liuchenyang","username":"liuchenyang","email":"2162059863@qq.com","commits":8,"url":"https://github.com/liuchenyang"}]},"readingTime":{"minutes":14.98,"words":4495},"filePathRelative":"interview/intervie_Kubernetes/intervie_Kubernetes.md","excerpt":"<h2>1.说下k8s的核心组件都有哪些，并简述下他们各自的作用</h2>\\n<p>答：</p>\\n<blockquote>\\n<p>Kubernetes（k8s）的核心组件可以分为<strong>控制平面（Control Plane）组件</strong>和<strong>工作节点（Node）组件</strong>两大类；</p>\\n</blockquote>\\n<ul class=\\"task-list-container\\">\\n<li class=\\"task-list-item\\"><input type=\\"checkbox\\" class=\\"task-list-item-checkbox\\" id=\\"task-item-0\\" checked=\\"checked\\" disabled=\\"disabled\\"><label class=\\"task-list-item-label\\" for=\\"task-item-0\\"> <strong>控制平面组件（Control Plane Components）</strong></label></li>\\n<li>etcd：分布式键值存储，保存集群状态。</li>\\n<li>kube-apiserver：提供 Kubernetes API，是整个集群的前端入口。</li>\\n<li>kube-scheduler：负责调度新创建的 Pod 到合适的工作节点上运行。</li>\\n<li>kube-controller-manager：运行控制器（如 Node Controller、Replication Controller）。</li>\\n<li class=\\"task-list-item\\"><input type=\\"checkbox\\" class=\\"task-list-item-checkbox\\" id=\\"task-item-1\\" checked=\\"checked\\" disabled=\\"disabled\\"><label class=\\"task-list-item-label\\" for=\\"task-item-1\\"> <strong>工作节点组件（Node Components）</strong></label></li>\\n<li>kubelet：节点上的主要代理，管理节点上的 Pod 和容器。</li>\\n<li>kube-proxy：负责<strong>网络代理和负载均衡</strong>，实现 Kubernetes Service 的通信。</li>\\n<li>Container Runtime：负责运行容器的软件（如 Docker、containerd）。</li>\\n</ul>","copyright":"著作权归 Mr.Liucy 所有，本站内容遵循 MIT 协议，转载请注明出处。\\n原文链接：https://liuchenyang.top/interview/intervie_Kubernetes/intervie_Kubernetes.html","autoDesc":true}`),s={name:`intervie_Kubernetes.md`};function c(r,o,s,c,l,u){let d=e(`Mermaid`);return t(),a(`div`,null,[o[0]||=n(`<h2 id="_1-说下k8s的核心组件都有哪些-并简述下他们各自的作用" tabindex="-1"><a class="header-anchor" href="#_1-说下k8s的核心组件都有哪些-并简述下他们各自的作用"><span>1.说下k8s的核心组件都有哪些，并简述下他们各自的作用</span></a></h2><p>答：</p><blockquote><p>Kubernetes（k8s）的核心组件可以分为<strong>控制平面（Control Plane）组件</strong>和<strong>工作节点（Node）组件</strong>两大类；</p></blockquote><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-0"><strong>控制平面组件（Control Plane Components）</strong></label></li><li>etcd：分布式键值存储，保存集群状态。</li><li>kube-apiserver：提供 Kubernetes API，是整个集群的前端入口。</li><li>kube-scheduler：负责调度新创建的 Pod 到合适的工作节点上运行。</li><li>kube-controller-manager：运行控制器（如 Node Controller、Replication Controller）。</li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-1"><strong>工作节点组件（Node Components）</strong></label></li><li>kubelet：节点上的主要代理，管理节点上的 Pod 和容器。</li><li>kube-proxy：负责<strong>网络代理和负载均衡</strong>，实现 Kubernetes Service 的通信。</li><li>Container Runtime：负责运行容器的软件（如 Docker、containerd）。</li></ul><h2 id="_2、k8s中都有哪些对象资源" tabindex="-1"><a class="header-anchor" href="#_2、k8s中都有哪些对象资源"><span>2、k8s中都有哪些对象资源？</span></a></h2><p>答：</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 工作负载类（Workload）</label></li></ul><table><thead><tr><th>资源名称</th><th>简称</th><th>作用</th></tr></thead><tbody><tr><td><strong>Pod</strong></td><td><code>po</code></td><td>最小部署单元，包含一个或多个紧密耦合的容器</td></tr><tr><td><strong>Deployment</strong></td><td><code>deploy</code></td><td>声明式管理无状态应用，支持滚动更新和回滚</td></tr><tr><td><strong>StatefulSet</strong></td><td><code>sts</code></td><td>管理有状态应用，提供稳定的网络标识和持久存储</td></tr><tr><td><strong>DaemonSet</strong></td><td><code>ds</code></td><td>确保每个（或指定）节点上运行一个 Pod 副本</td></tr><tr><td><strong>ReplicaSet</strong></td><td><code>rs</code></td><td>维护指定数量的 Pod 副本（通常被 Deployment 管理）</td></tr><tr><td><strong>Job</strong></td><td>-</td><td>一次性任务，运行完成后即结束</td></tr><tr><td><strong>CronJob</strong></td><td><code>cj</code></td><td>定时任务，按 Cron 表达式周期性执行 Job</td></tr><tr><td><strong>ReplicationController</strong></td><td><code>rc</code></td><td>旧版副本控制器（已被 ReplicaSet/Deployment 取代）</td></tr></tbody></table><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> 服务与网络类（Service &amp; Networking）</label></li></ul><table><thead><tr><th>资源名称</th><th>简称</th><th>作用</th></tr></thead><tbody><tr><td><strong>Service</strong></td><td><code>svc</code></td><td>为一组 Pod 提供稳定的网络访问入口（ClusterIP/NodePort/LoadBalancer/ExternalName）</td></tr><tr><td><strong>Ingress</strong></td><td><code>ing</code></td><td>管理外部 HTTP/HTTPS 访问，提供基于域名的路由</td></tr><tr><td><strong>IngressClass</strong></td><td>-</td><td>定义 Ingress 控制器的配置类</td></tr><tr><td><strong>NetworkPolicy</strong></td><td><code>netpol</code></td><td>定义 Pod 之间的网络访问策略（防火墙规则）</td></tr><tr><td><strong>EndpointSlice</strong></td><td>-</td><td>存储 Service 的后端端点信息（替代旧的 Endpoints）</td></tr><tr><td><strong>Endpoints</strong></td><td><code>ep</code></td><td>Service 对应的后端 Pod IP:Port 列表（逐渐被 EndpointSlice 取代）</td></tr></tbody></table><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> 配置与存储类（Config &amp; Storage）</label></li></ul><table><thead><tr><th>资源名称</th><th>简称</th><th>作用</th></tr></thead><tbody><tr><td><strong>ConfigMap</strong></td><td><code>cm</code></td><td>存储非敏感的配置数据（键值对、配置文件等）</td></tr><tr><td><strong>Secret</strong></td><td>-</td><td>存储敏感数据（密码、Token、证书等），Base64 编码</td></tr><tr><td><strong>PersistentVolume</strong></td><td><code>pv</code></td><td>集群中的持久化存储资源（由管理员配置或动态供给）</td></tr><tr><td><strong>PersistentVolumeClaim</strong></td><td><code>pvc</code></td><td>Pod 对持久化存储的请求声明</td></tr><tr><td><strong>StorageClass</strong></td><td><code>sc</code></td><td>定义存储的&quot;类&quot;，支持动态卷供给</td></tr><tr><td><strong>VolumeAttachment</strong></td><td>-</td><td>记录存储卷的挂载状态（CSI 使用）</td></tr><tr><td><strong>CSI Driver/Node</strong></td><td>-</td><td>容器存储接口相关资源</td></tr></tbody></table><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> 身份与权限类（RBAC &amp; Security）</label></li></ul><table><thead><tr><th>资源名称</th><th>简称</th><th>作用</th></tr></thead><tbody><tr><td><strong>ServiceAccount</strong></td><td><code>sa</code></td><td>为 Pod 提供身份标识，用于 API 认证</td></tr><tr><td><strong>Role</strong></td><td>-</td><td>定义命名空间级别的权限规则</td></tr><tr><td><strong>ClusterRole</strong></td><td>-</td><td>定义集群级别的权限规则</td></tr><tr><td><strong>RoleBinding</strong></td><td>-</td><td>将 Role 绑定到用户/组/ServiceAccount（命名空间级别）</td></tr><tr><td><strong>ClusterRoleBinding</strong></td><td>-</td><td>将 ClusterRole 绑定到用户/组/ServiceAccount（集群级别）</td></tr><tr><td><strong>PodSecurityPolicy</strong></td><td><code>psp</code></td><td>定义 Pod 的安全策略（已弃用，被 Pod Security Standards 替代）</td></tr><tr><td><strong>PodSecurityContext</strong></td><td>-</td><td>定义 Pod/容器的安全上下文（非独立资源，是字段）</td></tr></tbody></table><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> 调度与节点类（Scheduling &amp; Node）</label></li></ul><table><thead><tr><th>资源名称</th><th>简称</th><th>作用</th></tr></thead><tbody><tr><td><strong>Node</strong></td><td><code>no</code></td><td>集群中的工作节点（物理机或虚拟机）</td></tr><tr><td><strong>Namespace</strong></td><td><code>ns</code></td><td>资源隔离的虚拟集群（如 dev、test、prod）</td></tr><tr><td><strong>ResourceQuota</strong></td><td><code>quota</code></td><td>限制命名空间的资源使用总量</td></tr><tr><td><strong>LimitRange</strong></td><td><code>limits</code></td><td>设置命名空间中 Pod/容器的默认资源限制</td></tr><tr><td><strong>PriorityClass</strong></td><td><code>pc</code></td><td>定义 Pod 的调度优先级</td></tr><tr><td><strong>RuntimeClass</strong></td><td>-</td><td>定义不同的容器运行时配置</td></tr><tr><td><strong>Taint</strong> / <strong>Toleration</strong></td><td>-</td><td>节点污点与 Pod 容忍度（字段，非独立资源）</td></tr><tr><td><strong>Affinity</strong> / <strong>AntiAffinity</strong></td><td>-</td><td>Pod 亲和性与反亲和性（字段，非独立资源）</td></tr></tbody></table><h2 id="_3、labels-的本质是什么-他的作用又是什么" tabindex="-1"><a class="header-anchor" href="#_3、labels-的本质是什么-他的作用又是什么"><span>3、labels 的本质是什么？他的作用又是什么？</span></a></h2><p>答：Label其实就一对 <code>key/value</code> ，被关联到对象上。他可以起到服务发现和集群调度的作用。</p><h2 id="_4、service-在-k8s-中有哪几种类型" tabindex="-1"><a class="header-anchor" href="#_4、service-在-k8s-中有哪几种类型"><span>4、Service 在 K8s 中有哪几种类型？</span></a></h2><p>答：</p><table><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">名称</th><th style="text-align:left;">访问方式</th><th style="text-align:left;">典型使用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ClusterIP</strong></td><td style="text-align:left;">集群内部 IP</td><td style="text-align:left;">仅集群内部访问</td><td style="text-align:left;">微服务内部通信、数据库服务</td></tr><tr><td style="text-align:left;"><strong>NodePort</strong></td><td style="text-align:left;">节点端口</td><td style="text-align:left;"><code>&lt;NodeIP&gt;:&lt;NodePort&gt;</code></td><td style="text-align:left;">开发测试、简单外部访问</td></tr><tr><td style="text-align:left;"><strong>LoadBalancer</strong></td><td style="text-align:left;">云负载均衡器</td><td style="text-align:left;">云厂商提供的公网 IP</td><td style="text-align:left;">生产环境、云平台部署</td></tr><tr><td style="text-align:left;"><strong>ExternalName</strong></td><td style="text-align:left;">外部 DNS 别名</td><td style="text-align:left;">映射到外部域名</td><td style="text-align:left;">访问集群外服务、服务迁移过渡</td></tr></tbody></table><h2 id="_5、secret-在k8s中的作用" tabindex="-1"><a class="header-anchor" href="#_5、secret-在k8s中的作用"><span>5、Secret 在k8s中的作用？</span></a></h2><p>答：Secret 解决了密码、token、密钥等敏感数据的配置问题，而不需要把这些敏感数据暴露到镜像或者 Pod Spec中。</p><p>PS : 只有与 apiserver 组件进行交互的 pod 才会有如下的 证书、命名空间、tekon密钥。</p><h2 id="_6、简述下pv-和-pvc是什么" tabindex="-1"><a class="header-anchor" href="#_6、简述下pv-和-pvc是什么"><span>6、简述下PV 和 PVC是什么</span></a></h2><p>答：</p><p>PV - 持久卷：集群中<strong>预先配置好</strong>的存储资源，由管理员或动态供给创建。</p><p>PVC - 持久卷声明：用户对存储资源的<strong>申请请求</strong>，类似于 Pod 申请 CPU/内存。</p><ul><li>PV</li></ul><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">apiVersion</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">v1</span></span>
<span class="line"><span style="color:#E06C75;">kind</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">PersistentVolume</span></span>
<span class="line"><span style="color:#E06C75;">metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">nfs-pv</span></span>
<span class="line"><span style="color:#E06C75;">spec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  capacity</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    storage</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">10Gi</span><span style="color:#7F848E;font-style:italic;">          # 存储容量</span></span>
<span class="line"><span style="color:#E06C75;">  accessModes</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#98C379;">ReadWriteOnce</span><span style="color:#7F848E;font-style:italic;">        # 访问模式（RWO/RWX/ROX）</span></span>
<span class="line"><span style="color:#E06C75;">  persistentVolumeReclaimPolicy</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Retain</span><span style="color:#7F848E;font-style:italic;">  # 回收策略</span></span>
<span class="line"><span style="color:#E06C75;">  storageClassName</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">nfs</span><span style="color:#7F848E;font-style:italic;">    # 存储类</span></span>
<span class="line"><span style="color:#E06C75;">  nfs</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    server</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">192.168.1.100</span></span>
<span class="line"><span style="color:#E06C75;">    path</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">/data/k8s</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>PVC</li></ul><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">apiVersion</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">v1</span></span>
<span class="line"><span style="color:#E06C75;">kind</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">PersistentVolumeClaim</span></span>
<span class="line"><span style="color:#E06C75;">metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-pvc</span></span>
<span class="line"><span style="color:#E06C75;">  namespace</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">default</span></span>
<span class="line"><span style="color:#E06C75;">spec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  accessModes</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#98C379;">ReadWriteOnce</span></span>
<span class="line"><span style="color:#E06C75;">  resources</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    requests</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      storage</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">5Gi</span><span style="color:#7F848E;font-style:italic;">         # 申请 5GB 存储</span></span>
<span class="line"><span style="color:#E06C75;">  storageClassName</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">nfs</span><span style="color:#7F848E;font-style:italic;">    # 指定 StorageClass</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>在简单一句话就是：</p><p><strong>PV 是&quot;房子&quot;，PVC 是&quot;租房申请&quot;，Pod 是&quot;租客&quot;。</strong><br> 管理员建好房子（PV），用户提交申请（PVC），系统匹配钥匙（绑定），租客入住使用（Pod 挂载）。</p></blockquote><h2 id="_7、pv和pvc的生命周期" tabindex="-1"><a class="header-anchor" href="#_7、pv和pvc的生命周期"><span>7、PV和PVC的生命周期</span></a></h2><p>PV（PersistentVolume，持久卷）和 PVC（PersistentVolumeClaim，持久卷声明）的生命周期分为<strong>五个阶段</strong>：<strong>配置 → 绑定 → 使用 → 释放 → 回收</strong>。</p><ul><li>完整生命周期流程图</li></ul>`,36),i(d,{code:`eJxLL0osyFDwCeJSAALH6Jetvc/3rlMIKMovyyzOzM/LzEuPVdDVtVNwin6+e+LTdbMUnDLzUkCiYA1OYDnn6Cd79z+fskIhtBgu4wyWcYl+2d71bMo+haDUnNREhKwLWNY1+unsec+mbAPKJuckZuaCpQFsSTXA`}),o[1]||=n(`<h2 id="_8、pv卷都有哪些声明状态" tabindex="-1"><a class="header-anchor" href="#_8、pv卷都有哪些声明状态"><span>8、PV卷都有哪些声明状态</span></a></h2><p>PV（PersistentVolume）有四种生命周期状态：</p><table><thead><tr><th style="text-align:left;">状态</th><th style="text-align:left;">说明</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Available</strong></td><td style="text-align:left;">可用</td><td style="text-align:left;">PV 已创建，空闲未绑定，等待 PVC 来认领</td></tr><tr><td style="text-align:left;"><strong>Bound</strong></td><td style="text-align:left;">已绑定</td><td style="text-align:left;">PV 已成功绑定到某个 PVC，正在被使用</td></tr><tr><td style="text-align:left;"><strong>Released</strong></td><td style="text-align:left;">已释放</td><td style="text-align:left;">PVC 被删了，PV 还保留着数据，但<strong>不能复用</strong>，需要管理员处理</td></tr><tr><td style="text-align:left;"><strong>Failed</strong></td><td style="text-align:left;">失败</td><td style="text-align:left;">自动回收失败（通常很少见）</td></tr></tbody></table><p>状态流程图</p>`,4),i(d,{code:`eJxLL0osyFDwCeJSAALHaMeyxMycxKSc1FgFXV27moAwZ4Xnuyc+XTerRsEp2im/NC8lFqzSCS79tGPBy5lLahSco4NSc1ITi1OhKpzBKp6vW/h8QtvTiTOedXY/7VrxbEcrkFuj4Iik5EX7KqDM09nznk3Z9nTJxhdbltYouES7Ad0BMgoA44FCKQ==`}),o[2]||=n(`<h2 id="_9、简述kubernetes-replica-set-和-replication-controller-之间有什么区别" tabindex="-1"><a class="header-anchor" href="#_9、简述kubernetes-replica-set-和-replication-controller-之间有什么区别"><span>9、简述Kubernetes Replica Set 和 Replication Controller 之间有什么区别？</span></a></h2><p>答：两者几乎一样，都是确保在任何给定时间运行指定数量的 Pod 副本。不同之处在于RS 使用基于集合的选择器，而 Replication Controller 使用基于等式的选择器。</p><h2 id="_10、一般kubernetes是如何进行优雅的节点关机维护" tabindex="-1"><a class="header-anchor" href="#_10、一般kubernetes是如何进行优雅的节点关机维护"><span>10、一般Kubernetes是如何进行优雅的节点关机维护？</span></a></h2><p>答：由于Kubernetes节点运行大量Pod，因此在进行关机维护之前，建议先标记节点为不可调度（节点隔离），然后使用kubectl drain将该节点的Pod进行驱逐，等待所有pod都清除之后，在进行关机维护。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">                      节点维护流程</span><span style="color:#98C379;">                            │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">                                                             │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">  1.</span><span style="color:#98C379;"> 标记节点不可调度（Cordon）</span><span style="color:#98C379;">                                │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">         ↓</span><span style="color:#98C379;">                                                   │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">  2.</span><span style="color:#98C379;"> 驱逐节点上的</span><span style="color:#98C379;"> Pod（Drain）</span><span style="color:#98C379;">                                 │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">         ↓</span><span style="color:#98C379;">                                                   │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">  3.</span><span style="color:#98C379;"> 等待</span><span style="color:#98C379;"> Pod</span><span style="color:#98C379;"> 优雅终止（Graceful</span><span style="color:#98C379;"> Termination）</span><span style="color:#98C379;">                 │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">         ↓</span><span style="color:#98C379;">                                                   │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">  4.</span><span style="color:#98C379;"> 执行维护操作（关机/升级/重启）</span><span style="color:#98C379;">                            │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">         ↓</span><span style="color:#98C379;">                                                   │</span></span>
<span class="line"><span style="color:#61AFEF;">│</span><span style="color:#98C379;">  5.</span><span style="color:#98C379;"> 恢复节点（Uncordon）</span><span style="color:#98C379;">                                      │</span></span>
<span class="line"><span style="color:#61AFEF;">└─────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_11、configmap-和-secret是什么-他们有什么区别" tabindex="-1"><a class="header-anchor" href="#_11、configmap-和-secret是什么-他们有什么区别"><span>11、ConfigMap 和 Secret是什么，他们有什么区别？</span></a></h2><blockquote><p>ConfigMap 和 Secret 都是 Kubernetes 中用于服务与配置分离的的核心资源，将应用配置与容器解耦。两者功能相似，但适用场景和安全级别不同。</p><ul><li>ConfigMap：一般是明文配置，用于存储非敏感的配置数据。</li><li>Secret：一般是采用base64编码配置，用于存储敏感数据（如密码、密钥），需先将明文转化为base64编码，在写入Secret里。</li></ul></blockquote><ul><li><strong>详细对比</strong></li></ul><table><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">ConfigMap</th><th style="text-align:left;">Secret</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>用途</strong></td><td style="text-align:left;">存储非敏感配置（配置文件、环境变量、命令行参数）</td><td style="text-align:left;">存储敏感数据（密码、Token、证书、密钥）</td></tr><tr><td style="text-align:left;"><strong>编码方式</strong></td><td style="text-align:left;"><strong>明文存储</strong>（UTF-8 文本）</td><td style="text-align:left;"><strong>Base64 编码</strong>（非加密，仅编码）</td></tr><tr><td style="text-align:left;"><strong>数据大小限制</strong></td><td style="text-align:left;">1 MiB（ETCD 限制）</td><td style="text-align:left;">1 MiB（但建议 &lt; 500KB，因 API Server 内存开销大）</td></tr><tr><td style="text-align:left;"><strong>etcd 加密</strong></td><td style="text-align:left;">❌ 不加密</td><td style="text-align:left;">✅ 可启用静态加密（K8s 1.7+）</td></tr><tr><td style="text-align:left;"><strong>内存处理</strong></td><td style="text-align:left;">直接存储</td><td style="text-align:left;">存储在 tmpfs（内存文件系统），避免落盘</td></tr><tr><td style="text-align:left;"><strong>访问控制</strong></td><td style="text-align:left;">普通 RBAC</td><td style="text-align:left;">建议更严格的 RBAC 策略</td></tr><tr><td style="text-align:left;"><strong>类型区分</strong></td><td style="text-align:left;">无类型</td><td style="text-align:left;">多种内置类型（Opaque、tls、docker-registry 等）</td></tr></tbody></table><h2 id="_12、什么是-statefulset" tabindex="-1"><a class="header-anchor" href="#_12、什么是-statefulset"><span>12、什么是 StatefulSet？</span></a></h2><p>答：StatefulSet 是 Kubernetes 中专门用于管理<strong>有状态应用</strong>的工作负载控制器，为 Pod 提供<strong>稳定的网络标识、持久存储和有序部署</strong>能力。</p><h2 id="_13、什么是-service" tabindex="-1"><a class="header-anchor" href="#_13、什么是-service"><span>13、什么是 Service？</span></a></h2><p>答：Service 简称 svc，用于定义一组 Pod 的访问策略，提供负载均衡和服务发现。</p><h2 id="_14、什么是-daemonset" tabindex="-1"><a class="header-anchor" href="#_14、什么是-daemonset"><span>14、什么是 DaemonSet？</span></a></h2><p>答：DaemonSet 简称 DS，用于在每个节点上运行一个 Pod 副本，通常用于日志收集、监控或网络代理。</p><h2 id="_15、什么是-ingress" tabindex="-1"><a class="header-anchor" href="#_15、什么是-ingress"><span>15、什么是 Ingress？</span></a></h2><p>答：Ingress 是 Kubernetes 中管理<strong>外部 HTTP/HTTPS 访问</strong>的 API 对象，提供<strong>基于域名的路由</strong>和<strong>负载均衡</strong>能力，是 Service 的&quot;上层网关&quot;。</p><h2 id="_16、service的类型有几种-都是什么" tabindex="-1"><a class="header-anchor" href="#_16、service的类型有几种-都是什么"><span>16、service的类型有几种，都是什么？</span></a></h2><table><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">ClusterIP</td><td style="text-align:left;">集群内部访问（默认）</td></tr><tr><td style="text-align:left;">NodePort</td><td style="text-align:left;">暴露节点端口，外部可访问</td></tr><tr><td style="text-align:left;">LoadBalancer</td><td style="text-align:left;">云厂商负载均衡器，分配公网 IP</td></tr><tr><td style="text-align:left;">ExternalName</td><td style="text-align:left;">映射外部域名</td></tr></tbody></table><h2 id="_17、ingress-与-service-的关系" tabindex="-1"><a class="header-anchor" href="#_17、ingress-与-service-的关系"><span>17、Ingress 与 Service 的关系</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">外部流量</span><span style="color:#98C379;"> →</span><span style="color:#ABB2BF;"> [Ingress] → [Service] → [Pod]</span></span>
<span class="line"><span style="color:#61AFEF;">              ↑</span><span style="color:#98C379;">            ↑</span></span>
<span class="line"><span style="color:#61AFEF;">           七层路由</span><span style="color:#98C379;">      四层转发</span></span>
<span class="line"><span style="color:#ABB2BF;">        (</span><span style="color:#61AFEF;">域名/路径/SSL</span><span style="color:#ABB2BF;">)  (</span><span style="color:#61AFEF;">ClusterIP</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>Ingress 是集群的&quot;智能网关&quot;，把外部 HTTP 流量按域名和路径路由到内部 Service，实现统一的入口管理。</p></blockquote><h2 id="_18、如何定义资源清单中的环境变量" tabindex="-1"><a class="header-anchor" href="#_18、如何定义资源清单中的环境变量"><span>18、如何定义资源清单中的环境变量？</span></a></h2><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">apiVersion</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">v1</span></span>
<span class="line"><span style="color:#E06C75;">kind</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Pod</span></span>
<span class="line"><span style="color:#E06C75;">metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-pod</span></span>
<span class="line"><span style="color:#E06C75;">spec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  containers</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">  - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-container</span></span>
<span class="line"><span style="color:#E06C75;">    image</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">nginx</span></span>
<span class="line"><span style="color:#E06C75;">    env</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 直接定义</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">ENV_NAME</span></span>
<span class="line"><span style="color:#E06C75;">      value</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;production&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 从 ConfigMap 引用</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">DB_HOST</span></span>
<span class="line"><span style="color:#E06C75;">      valueFrom</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        configMapKeyRef</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">          name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-config</span></span>
<span class="line"><span style="color:#E06C75;">          key</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">db-host</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 从 Secret 引用</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">DB_PASSWORD</span></span>
<span class="line"><span style="color:#E06C75;">      valueFrom</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        secretKeyRef</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">          name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">db-secret</span></span>
<span class="line"><span style="color:#E06C75;">          key</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">password</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 从 Downward API 引用</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">POD_NAME</span></span>
<span class="line"><span style="color:#E06C75;">      valueFrom</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        fieldRef</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">          fieldPath</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">metadata.name</span></span>
<span class="line"><span style="color:#ABB2BF;">    </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 批量引用 ConfigMap 和 Secret</span></span>
<span class="line"><span style="color:#E06C75;">    envFrom</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#E06C75;">configMapRef</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">app-config</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#E06C75;">secretRef</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">app-secret</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_19、资源清单中的-apiversion-字段有什么作用" tabindex="-1"><a class="header-anchor" href="#_19、资源清单中的-apiversion-字段有什么作用"><span>19、资源清单中的 apiVersion 字段有什么作用？</span></a></h2><p>答:</p><p><code>apiVersion</code> 字段用于指定创建资源时使用的 <strong>Kubernetes API 版本</strong>。</p><p>简单来说，它的作用是：</p><ol><li><strong>告诉 Kubernetes 使用哪个 API 来创建资源</strong>（不同的版本可能字段不同）</li><li><strong>区分资源是属于稳定版还是测试版</strong>（例如 <code>v1</code> 代表稳定，<code>beta</code> 代表测试）</li></ol><p><strong>常见示例：</strong></p><ul><li><code>apps/v1</code>：用于 Deployment、StatefulSet</li><li><code>v1</code>：用于 Pod、Service、ConfigMap</li><li><code>batch/v1</code>：用于 Job、CronJob</li></ul><h2 id="_20、如何定义资源清单中的资源限制-resource-limits" tabindex="-1"><a class="header-anchor" href="#_20、如何定义资源清单中的资源限制-resource-limits"><span>20、如何定义资源清单中的资源限制（Resource Limits）？</span></a></h2><p>答： 在 Kubernetes 资源清单中，通过<code>resources.requests</code> 和 <code>resources.limits</code> 字段来定义资源限制。</p><ul><li><p><code>requests</code>: 容器启动时请求的资源。</p></li><li><p><code>limits</code>: 容器资源使用的上限。</p></li></ul><p>示例：</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">apiVersion</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">v1</span></span>
<span class="line"><span style="color:#E06C75;">kind</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Pod</span></span>
<span class="line"><span style="color:#E06C75;">metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-pod</span></span>
<span class="line"><span style="color:#E06C75;">spec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  containers</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">  - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-container</span></span>
<span class="line"><span style="color:#E06C75;">    image</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">nginx</span></span>
<span class="line"><span style="color:#E06C75;">    resources</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      requests</span><span style="color:#ABB2BF;">:    </span><span style="color:#7F848E;font-style:italic;"># 调度时保证的最小资源</span></span>
<span class="line"><span style="color:#E06C75;">        cpu</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;250m&quot;</span><span style="color:#7F848E;font-style:italic;">      # 0.25 核 CPU</span></span>
<span class="line"><span style="color:#E06C75;">        memory</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;512Mi&quot;</span><span style="color:#7F848E;font-style:italic;">  # 512 MiB 内存</span></span>
<span class="line"><span style="color:#E06C75;">      limits</span><span style="color:#ABB2BF;">:      </span><span style="color:#7F848E;font-style:italic;"># 运行时不能超过的最大资源</span></span>
<span class="line"><span style="color:#E06C75;">        cpu</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;500m&quot;</span><span style="color:#7F848E;font-style:italic;">      # 0.5 核 CPU</span></span>
<span class="line"><span style="color:#E06C75;">        memory</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;1Gi&quot;</span><span style="color:#7F848E;font-style:italic;">    # 1 GiB 内存</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>CPU 单位说明</strong></p><ul><li><code>1</code> = 1 核（vCPU/超线程）</li><li><code>100m</code> = 0.1 核（100 milliCPU）</li><li>最小单位：<code>1m</code></li></ul><p><strong>内存单位说明</strong></p><ul><li><code>Mi</code>：Mebibytes（二进制，1Mi = 1024×1024 字节）</li><li><code>M</code> 或 <code>MB</code>：Megabytes（十进制，1M = 1000×1000 字节）</li><li><code>Gi</code>：Gibibytes（二进制，1Gi = 1024Mi）</li><li><code>Ki</code>、<code>K</code> 类似</li></ul><blockquote><p>注意事项：</p><ul><li><strong>requests 必须 ≤ limits</strong></li><li>如果只设置 <code>limits</code>，<code>requests</code> 默认等于 <code>limits</code></li><li>CPU 是可压缩资源（超过限制会限流，不会 kill）</li><li>内存是不可压缩资源（超过限制会 OOM kill）</li></ul></blockquote><h2 id="_21、超过资源清单中的限制会怎么样" tabindex="-1"><a class="header-anchor" href="#_21、超过资源清单中的限制会怎么样"><span>21、超过资源清单中的限制会怎么样？</span></a></h2><ul><li>CPU 是可压缩资源（超过限制会限流，不会 kill）</li><li>内存是不可压缩资源（超过限制会 OOM kill）</li></ul><h2 id="_22、不设置资源限制会有什么后果" tabindex="-1"><a class="header-anchor" href="#_22、不设置资源限制会有什么后果"><span>22、不设置资源限制会有什么后果？</span></a></h2><ul><li>容器可能耗尽节点所有资源</li><li>影响同节点其他 Pod 正常运行</li><li>节点资源不足时，无限制的 Pod 可能被驱逐</li></ul><h2 id="_23、如何定义-pod-的健康检查" tabindex="-1"><a class="header-anchor" href="#_23、如何定义-pod-的健康检查"><span>23、如何定义 Pod 的健康检查</span></a></h2><p>答： 通过添加探针来定义 Pod 的健康检查。</p><ul><li><code>livenessProbe</code>: 检查容器是否存活。</li><li><code>readinessProbe</code>: 检查容器是否准备好接收流量。</li></ul><h2 id="_24、探针的监控检查方式都有哪些" tabindex="-1"><a class="header-anchor" href="#_24、探针的监控检查方式都有哪些"><span>24、探针的监控检查方式都有哪些？</span></a></h2><h3 id="_24-1-http-get-检查" tabindex="-1"><a class="header-anchor" href="#_24-1-http-get-检查"><span>24.1 HTTP GET 检查</span></a></h3><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">apiVersion</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">v1</span></span>
<span class="line"><span style="color:#E06C75;">kind</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Pod</span></span>
<span class="line"><span style="color:#E06C75;">metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-pod</span></span>
<span class="line"><span style="color:#E06C75;">spec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  containers</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">  - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-container</span></span>
<span class="line"><span style="color:#E06C75;">    image</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">nginx</span></span>
<span class="line"><span style="color:#E06C75;">    livenessProbe</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      httpGet</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        path</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">/healthz</span><span style="color:#7F848E;font-style:italic;">     # 检查路径</span></span>
<span class="line"><span style="color:#E06C75;">        port</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">80</span><span style="color:#7F848E;font-style:italic;">           # 检查端口</span></span>
<span class="line"><span style="color:#E06C75;">        httpHeaders</span><span style="color:#ABB2BF;">:       </span><span style="color:#7F848E;font-style:italic;"># 可选：自定义请求头</span></span>
<span class="line"><span style="color:#ABB2BF;">        - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Custom-Header</span></span>
<span class="line"><span style="color:#E06C75;">          value</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Awesome</span></span>
<span class="line"><span style="color:#E06C75;">      initialDelaySeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">5</span><span style="color:#7F848E;font-style:italic;">   # 容器启动后延迟多少秒开始检查</span></span>
<span class="line"><span style="color:#E06C75;">      periodSeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">10</span><span style="color:#7F848E;font-style:italic;">        # 检查间隔（秒）</span></span>
<span class="line"><span style="color:#E06C75;">      timeoutSeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">1</span><span style="color:#7F848E;font-style:italic;">        # 超时时间（秒）</span></span>
<span class="line"><span style="color:#E06C75;">      successThreshold</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">1</span><span style="color:#7F848E;font-style:italic;">      # 成功几次才算成功</span></span>
<span class="line"><span style="color:#E06C75;">      failureThreshold</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">3</span><span style="color:#7F848E;font-style:italic;">      # 失败几次才算失败</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_24-2-tcp-socket-检查" tabindex="-1"><a class="header-anchor" href="#_24-2-tcp-socket-检查"><span>24.2 TCP Socket 检查</span></a></h3><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">readinessProbe</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  tcpSocket</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    port</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">8080</span></span>
<span class="line"><span style="color:#E06C75;">  initialDelaySeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">5</span></span>
<span class="line"><span style="color:#E06C75;">  periodSeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">10</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_24-3-exec-命令检查" tabindex="-1"><a class="header-anchor" href="#_24-3-exec-命令检查"><span>24.3 Exec 命令检查</span></a></h3><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">livenessProbe</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  exec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    command</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#98C379;">cat</span></span>
<span class="line"><span style="color:#ABB2BF;">    - </span><span style="color:#98C379;">/tmp/healthy</span></span>
<span class="line"><span style="color:#E06C75;">  initialDelaySeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">15</span></span>
<span class="line"><span style="color:#E06C75;">  periodSeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">20</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_25、两种探针的区别" tabindex="-1"><a class="header-anchor" href="#_25、两种探针的区别"><span>25、两种探针的区别</span></a></h2><table><thead><tr><th style="text-align:left;">探针类型</th><th style="text-align:left;">作用</th><th style="text-align:left;">失败后果</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>livenessProbe</strong></td><td style="text-align:left;">检查容器是否存活</td><td style="text-align:left;">失败则重启容器</td></tr><tr><td style="text-align:left;"><strong>readinessProbe</strong></td><td style="text-align:left;">检查容器是否准备好提供服务</td><td style="text-align:left;">失败则从 Service 端点中移除，不转发流量</td></tr></tbody></table><p>示例：</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">apiVersion</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">apps/v1</span></span>
<span class="line"><span style="color:#E06C75;">kind</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Deployment</span></span>
<span class="line"><span style="color:#E06C75;">metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">web-app</span></span>
<span class="line"><span style="color:#E06C75;">spec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  replicas</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">3</span></span>
<span class="line"><span style="color:#E06C75;">  selector</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    matchLabels</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      app</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">web</span></span>
<span class="line"><span style="color:#E06C75;">  template</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      labels</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        app</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">web</span></span>
<span class="line"><span style="color:#E06C75;">    spec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      containers</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">      - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">app</span></span>
<span class="line"><span style="color:#E06C75;">        image</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">myapp:v1</span></span>
<span class="line"><span style="color:#E06C75;">        ports</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">        - </span><span style="color:#E06C75;">containerPort</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">8080</span></span>
<span class="line"><span style="color:#ABB2BF;">        </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # 就绪检查：应用是否准备好接收流量</span></span>
<span class="line"><span style="color:#E06C75;">        readinessProbe</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">          httpGet</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">            path</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">/ready</span></span>
<span class="line"><span style="color:#E06C75;">            port</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">8080</span></span>
<span class="line"><span style="color:#E06C75;">          initialDelaySeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">10</span><span style="color:#7F848E;font-style:italic;">   # 给应用10秒启动时间</span></span>
<span class="line"><span style="color:#E06C75;">          periodSeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">5</span><span style="color:#7F848E;font-style:italic;">           # 每5秒检查一次</span></span>
<span class="line"><span style="color:#E06C75;">          failureThreshold</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">3</span><span style="color:#7F848E;font-style:italic;">        # 连续3次失败标记为未就绪</span></span>
<span class="line"><span style="color:#ABB2BF;">        </span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # 存活检查：应用是否正常运行</span></span>
<span class="line"><span style="color:#E06C75;">        livenessProbe</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">          httpGet</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">            path</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">/health</span></span>
<span class="line"><span style="color:#E06C75;">            port</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">8080</span></span>
<span class="line"><span style="color:#E06C75;">          initialDelaySeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">30</span><span style="color:#7F848E;font-style:italic;">    # 给应用30秒初始化</span></span>
<span class="line"><span style="color:#E06C75;">          periodSeconds</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">10</span><span style="color:#7F848E;font-style:italic;">           # 每10秒检查一次</span></span>
<span class="line"><span style="color:#E06C75;">          failureThreshold</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">3</span><span style="color:#7F848E;font-style:italic;">         # 连续3次失败重启容器</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>initialDelaySeconds</strong> 要设置足够长，避免应用未启动就开始检查</li><li><strong>periodSeconds</strong> 不要太频繁（5-10秒较合适）</li><li><strong>timeoutSeconds</strong> 通常设置 1-5 秒</li><li><strong>failureThreshold</strong> 设置 2-3 次，避免误判</li><li>检查接口要轻量级，不要执行复杂逻辑</li><li>区分好 liveness 和 readiness 的职责</li></ul><h2 id="_26、pod的生命周期" tabindex="-1"><a class="header-anchor" href="#_26、pod的生命周期"><span>26、pod的生命周期</span></a></h2><p>Pod对象从创建开始至终止退出的时间范围称为生命周期。在此期间，Pod会经历多种状态并执行一系列操作。其中，创建主容器是必需执行的操作；其他操作如初始化容器（Init Container）、容器启动后钩子（PostStart Hook）、容器终止前钩子（PreStop Hook）、存活性探测（Liveness Probe）和就绪性探测（Readiness Probe）等，则根据Pod的定义选择性执行。</p><h2 id="_27、描述-pod-从创建到终止的完整生命周期过程" tabindex="-1"><a class="header-anchor" href="#_27、描述-pod-从创建到终止的完整生命周期过程"><span>27、描述 Pod 从创建到终止的完整生命周期过程</span></a></h2><p>Pod 的生命周期从创建到终止大概分这么几步：</p><p>首先，用户通过 kubectl 创建 Pod，请求写到 etcd 后，调度器把 Pod 分配到一个节点上，节点的 kubelet 就开始干活了。</p><p>kubelet 第一件事是先启动一个 <strong>pause 容器</strong>，这个容器不干别的，就是给 Pod hold 住网络和命名空间，所有业务容器都共享它。</p><p>接着如果有 <strong>Init 容器</strong>，就按顺序跑，它们必须成功退出（返回0），主容器才会启动，不然就一直重试。</p><p>主容器启动后，如果有 <strong>PostStart 钩子</strong>就会执行一下。然后 kubelet 会根据配置开始做两种探测：</p><ul><li><strong>就绪探测</strong>：判断容器能不能接收流量，通过了 Pod 才变成 Running 状态，并且 Service 才会把流量转发进来</li><li><strong>存活探测</strong>：全程盯着容器，如果发现应用死了（探测失败），就按策略重启容器</li></ul><p>最后如果 Pod 被删了，kubelet 会先执行 <strong>PreStop 钩子</strong>做清理，然后发 SIGTERM 信号给容器，给它一个优雅退出的时间（默认30秒），时间到了还没退就强制 SIGKILL 杀掉，最后 pause 容器也被清理，Pod 彻底消失。”</p><hr><ul><li>流程图展示</li></ul>`,72),i(d,{code:``}),o[3]||=n(`<h2 id="_28、pod-生命周期有哪些主要阶段" tabindex="-1"><a class="header-anchor" href="#_28、pod-生命周期有哪些主要阶段"><span>28、Pod 生命周期有哪些主要阶段？</span></a></h2><ul><li><strong>Pending</strong>：Pod 刚创建，正在等调度或者拉取镜像，容器还没起来；</li><li><strong>Running</strong>：Pod 已经分配到节点，所有容器都创建好了，至少有一个在运行；</li><li><strong>Succeeded</strong>：Pod 里的所有容器都正常退出（比如跑完一个 Job），不会再重启；</li><li><strong>Failed</strong>：容器退出了，但至少有一个是异常退出（非0返回码）；</li><li><strong>Unknown</strong>：Pod 的状态获取不到，通常是节点宕机或者网络不通，apiserver 联系不上 kubelet。</li></ul><h2 id="_29、service-account的作用" tabindex="-1"><a class="header-anchor" href="#_29、service-account的作用"><span>29、Service Account的作用</span></a></h2><p>答：</p><blockquote><p><code>Service Account</code> 是 Pod 访问 Kubernetes API 时的身份凭证，通过它结合 RBAC 可以精细控制 Pod 能做什么操作，比如一个应用想查询其他 Pod 的状态，就需要用 Service Account 来认证授权。</p></blockquote><p><strong>详细说明：</strong></p><ol><li><strong>身份认证</strong></li></ol><ul><li>当 Pod 需要访问 API Server（比如查询其他 Pod 状态、更新资源）时，需要使用 Service Account 进行身份认证</li><li>每个 Pod 都必须绑定一个 Service Account（如果不指定，会自动使用所在 Namespace 的 <code>default</code>）</li></ul><ol start="2"><li><strong>权限控制</strong></li></ol><ul><li>Service Account 通常与 RBAC（基于角色的访问控制）结合使用</li><li>通过 Role/ClusterRole + RoleBinding 来授予不同的操作权限</li></ul><ol start="3"><li><strong>自动挂载凭证</strong></li></ol><ul><li>当 Pod 使用 Service Account 时，Kubernetes 会自动将对应的认证信息（token）通过 Volume 挂载到 Pod 的 <code>/var/run/secrets/kubernetes.io/serviceaccount/</code> 目录</li><li>Pod 里的应用可以用这个 token 来认证自己，访问 API</li></ul><p>示例：</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#7F848E;font-style:italic;"># 创建一个 Service Account</span></span>
<span class="line"><span style="color:#E06C75;">apiVersion</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">v1</span></span>
<span class="line"><span style="color:#E06C75;">kind</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">ServiceAccount</span></span>
<span class="line"><span style="color:#E06C75;">metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-sa</span></span>
<span class="line"><span style="color:#ABB2BF;">---</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在 Pod 中指定使用它</span></span>
<span class="line"><span style="color:#E06C75;">apiVersion</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">v1</span></span>
<span class="line"><span style="color:#E06C75;">kind</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Pod</span></span>
<span class="line"><span style="color:#E06C75;">metadata</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-pod</span></span>
<span class="line"><span style="color:#E06C75;">spec</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  serviceAccountName</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">my-sa</span><span style="color:#7F848E;font-style:italic;">  # 指定 Service Account</span></span>
<span class="line"><span style="color:#E06C75;">  containers</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">  - </span><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">app</span></span>
<span class="line"><span style="color:#E06C75;">    image</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">nginx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果不指定 <code>serviceAccountName</code>，Pod 会使用该 Namespace 下的 <code>default</code> Service Account。</p>`,15)])}var l=r(s,[[`render`,c]]);export{o as _pageData,l as default};